<div class="form-card card"><form method="post" action="?page=users&action=<?=$mode==='create'?'store':'update&id='.$user['id']?>"><?=$csrfField?><div class="form-grid"><label>Username<input name="username" required value="<?=e($user['username']??'')?>"><?php if(isset($errors['username'])):?><small class="field-error"><?=e($errors['username'])?></small><?php endif;?></label><label>Nama<input name="name" required value="<?=e($user['name']??'')?>"></label><label>Email<input type="email" name="email" value="<?=e($user['email']??'')?>"></label><label>Role<select name="role"><option <?=($user['role']??'')==='Member'?'selected':''?>>Member</option><option value="WarehouseStaff" <?=($user['role']??'')==='WarehouseStaff'?'selected':''?>>Petugas Gudang</option><option <?=($user['role']??'')==='Admin'?'selected':''?>>Admin</option></select></label><label>Password<?= $mode==='edit'?'<small class="muted">Kosongkan jika tidak diubah.</small>':''?><input type="password" name="password" <?=$mode==='create'?'required':''?>><?php if(isset($errors['password'])):?><small class="field-error"><?=e($errors['password'])?></small><?php endif;?></label><label>Status<select name="is_active"><option value="1" <?=($user['is_active']??1)?'selected':''?>>Active</option><option value="0" <?=!($user['is_active']??1)?'selected':''?>>Inactive</option></select></label></div><div class="form-actions"><a class="btn" href="?page=users">Cancel</a><button class="btn btn-primary">Save</button></div></form></div>
